text:
{
  "design": {
    "theme": "studio",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall gases and evidence of a chemical reaction",
      "look_at": {
        "kind": "picture",
        "shows": "Magnesium reacting with acid and producing bubbles"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Predict the effect of concentration",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 4,
      "does": "Teach the gas collection apparatus",
      "look_at": {
        "kind": "diagram",
        "shows": "A sealed flask connected to a gas syringe"
      },
      "teaches": [2]
    },
    {
      "slide": 5,
      "does": "Teach a controlled and repeatable investigation",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 6,
      "does": "Model a mean rate calculation",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Check a near-identical mean rate calculation",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1]
    },
    {
      "slide": 8,
      "does": "Explain concentration through collision theory",
      "look_at": {
        "kind": "diagram",
        "shows": "More acid particles in the same volume around equal magnesium pieces"
      },
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Correct the belief that concentration makes particles move faster",
      "look_at": {
        "kind": "diagram",
        "shows": "Different particle numbers but equal speed arrows at the same temperature"
      },
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Check the collision theory explanation",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 11,
      "does": "Apply fair-test reasoning to a flawed investigation",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2, 3]
    },
    {
      "slide": 12,
      "does": "Apply rate calculations and explanations to new results",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Rates of reaction",
    "lead": "Recall: which gas forms when magnesium reacts with hydrochloric acid? What visible evidence shows a reaction?",
    "picture": {
      "shows": "Magnesium ribbon reacting with dilute hydrochloric acid in a laboratory flask",
      "must_see": [
        "magnesium ribbon",
        "colourless liquid",
        "bubbles around metal"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "question-set",
      "heading": "Make a prediction",
      "questions": [
        "Two flasks contain 25 cm³ of hydrochloric acid: one at 0.5 mol/dm³ and one at 1.0 mol/dm³. Equal magnesium pieces are added at the same temperature. Which will produce gas faster?",
        "Predict how the gas volumes collected after 20 seconds will compare.",
        "Suggest a reason for your prediction."
      ],
      "instruction": "Write a prediction and a reason.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Collect the gas",
      "lead": "Magnesium + hydrochloric acid → magnesium chloride + hydrogen",
      "points": [
        "Hydrogen travels through the delivery tube.",
        "The gas syringe measures volume in cm³.",
        "A stopwatch measures elapsed time in seconds."
      ],
      "figure": {
        "kind": "labelled-diagram",
        "shows": "A conical flask containing hydrochloric acid and magnesium ribbon, sealed with a bung and connected by a delivery tube to a horizontal, clamped gas syringe. Show a stopwatch alongside it.",
        "labels": [
          "hydrochloric acid",
          "magnesium ribbon",
          "bung",
          "delivery tube",
          "gas syringe",
          "clamp stand",
          "stopwatch"
        ]
      }
    },
    {
      "template": "steps",
      "heading": "Investigate concentration",
      "points": [
        "Measure 25 cm³ of acid. Set its temperature to 20°C.",
        "Add 0.040 g of magnesium ribbon; start timing and seal immediately.",
        "Record gas volume every 10 seconds for 60 seconds.",
        "Repeat with 0.5, 1.0 and 1.5 mol/dm³ acid; keep magnesium mass, ribbon width, acid volume and temperature constant.",
        "Repeat each concentration three times. Calculate the mean gas volume at each time."
      ],
      "figure": null
    },
    {
      "template": "equation-hero",
      "heading": "Worked example: mean rate",
      "lead": "A reaction produces 48 cm³ of hydrogen in its first 30 s.",
      "formula": "mean rate = gas volume ÷ time",
      "points": [
        "Mean rate = 48 ÷ 30",
        "Mean rate = 1.6 cm³/s"
      ],
      "figure": null
    },
    {
      "template": "practice",
      "heading": "Calculate the mean rate",
      "questions": [
        "A reaction produces 54 cm³ of hydrogen in its first 30 s. Calculate its mean rate.",
        "A reaction produces 72 cm³ in its first 60 s. Calculate its mean rate.",
        "What does a mean rate of 2.0 cm³/s tell you about gas production?"
      ],
      "instruction": "Write the formula, substitution and answer with units.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Why does concentration matter?",
      "lead": "Increasing concentration puts more acid particles in each cm³.",
      "points": [
        "Acid particles collide with the magnesium surface more often.",
        "Successful collisions have enough energy to react.",
        "More successful collisions each second give a faster rate."
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-sized panels at the same temperature. Each contains an identical magnesium strip along its lower edge. The higher-concentration panel contains twice as many acid particles. Use movement arrows of the same range of lengths in both panels.",
        "labels": [
          "Lower concentration",
          "Higher concentration",
          "Same temperature"
        ]
      }
    },
    {
      "template": "visual-text",
      "heading": "More particles, not faster particles",
      "lead": "Doubling acid concentration at 20°C does not make particles move faster.",
      "points": [
        {
          "label": "Concentration",
          "text": "More particles per cm³; more collisions each second."
        },
        {
          "label": "Temperature",
          "text": "Unchanged: average particle kinetic energy stays the same."
        }
      ],
      "figure": {
        "kind": "particles",
        "shows": "Two equal-volume acid samples at 20°C beside identical magnesium surfaces. One has twice as many acid particles. Both have the same distribution of movement-arrow lengths, showing unchanged average speed.",
        "labels": [
          "0.5 mol/dm³",
          "1.0 mol/dm³",
          "Both at 20°C"
        ]
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the best explanation",
      "stem": "Why does more concentrated acid react faster with equal magnesium pieces at the same temperature?",
      "options": [
        "Acid particles move faster.",
        "Successful collisions occur more often.",
        "Each acid particle becomes larger.",
        "Every collision becomes successful."
      ],
      "correct": 2
    },
    {
      "template": "practice",
      "heading": "Repair the investigation",
      "questions": [
        "Trial A uses 25 cm³ of 0.5 mol/dm³ acid at 20°C and 0.040 g magnesium. Trial B uses 25 cm³ of 1.0 mol/dm³ acid at 30°C and 0.080 g magnesium. Explain why this is not a fair test of concentration.",
        "Rewrite Trial B to make a fair comparison with Trial A. Use magnesium ribbon of the same width.",
        "Describe how to measure gas volume over time and make the results more reliable."
      ],
      "instruction": "Write a corrected method.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Use new results",
      "questions": [
        "Equal magnesium pieces react with equal acid volumes at 20°C. In 20 s, 0.5 mol/dm³ acid produces 16 cm³ of gas and 1.0 mol/dm³ produces 28 cm³. Calculate both mean rates.",
        "Explain the difference using particles and successful collisions.",
        "Stretch: both reactions eventually produce 40 cm³. Acid is in excess in both. Explain why faster does not mean more gas in total."
      ],
      "instruction": "Show your working and explain your reasoning.",
      "picture": null
    }
  ]
}
